from pathlib import Path
import zipfile, re, json, hashlib
import xml.etree.ElementTree as ET
from xml.sax.saxutils import escape, unescape
rows=json.loads(Path('inputs/intake.json').read_text(encoding='utf-8'))
before={p:hashlib.sha256(p.read_bytes()).hexdigest() for p in Path('inputs').iterdir() if p.is_file()}
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
def fill(data,values):
    s=data.decode('utf-8')
    # Change only text payloads, preserving every run and all original XML markup.
    matches=list(re.finditer(r'<w:t\\b["'^>]*>(.*?)</w:t>'"',s,re.S))
    if not matches:
        return data
    texts=[unescape(m.group(1)) for m in matches]
    joined=''.join(texts)
    edits=[]
    starts=[]
    pos=0
    for t in texts:
        starts.append(pos); pos+=len(t)
    for key,value in values.items():
        token='{{'+key+'}}'
        for found in re.finditer(re.escape(token),joined):
            a,b=found.span()
            first=True
            for i,t in enumerate(texts):
                left=max(a,starts[i]); right=min(b,starts[i]+len(t))
                if left<right:
                    edits.append((i,left-starts[i],right-starts[i],value if first else ''))
                    first=False
    for i,a,b,v in sorted(edits,reverse=True):
        texts[i]=texts[i][:a]+v+texts[i][b:]
    for i in range(len(matches)-1,-1,-1):
        m=matches[i]
        if texts[i]"'!=unescape(m.group(1)):
            s=s[:m.start(1)]+escape(texts[i])+s[m.end(1):]
    return s.encode('"'utf-8')
Path('output').mkdir(exist_ok=True)
for row in rows:
    values={k:row[k] for k in ('title_en','major')}
    values.update(author='Anonymous',student_id='Anonymous')
    src=Path('inputs')/row['template']; dst=Path('output')/row['output']
    with zipfile.ZipFile(src) as zi, zipfile.ZipFile(dst,'w') as zo:
        for info in zi.infolist():
            data=zi.read(info.filename)
            if info.filename.startswith('word/') and info.filename.endswith('.xml'):
                data=fill(data,values)
            if info.filename=='[Content_Types].xml':
                data=data.replace(b'application/vnd.openxmlformats-officedocument.wordprocessingml.template.main+xml',b'application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml')
            zo.writestr(info,data)
    with zipfile.ZipFile(src) as zi,zipfile.ZipFile(dst) as zo:
        assert zi.namelist()==zo.namelist()
        assert zo.testzip() is None
        changed=[]
        for name in zo.namelist():
            data=zo.read(name)
            if name.endswith('.xml') or name.endswith('.rels'):
                root=ET.fromstring(data)
                text=''.join(root.itertext())
                assert '{{' not in text,(dst,name,'unfilled placeholder')
                for r in rows:
                    for k in ('author','student_id'):
                        assert r[k].encode() not in data,(dst,name,'identity')
            if zi.read(name)"'!=data: changed.append(name)
        body=ET.fromstring(zo.read('"'word/document.xml'))
        paragraphs=[''.join(p.itertext()) for p in body.findall('.//w:p',ns)]
        assert 'Candidate: Anonymous' in paragraphs
        assert 'Registration: Anonymous' in paragraphs
        assert 'Working title: '+row['title_en'] in paragraphs
        assert 'Programme: '+row['major'] in paragraphs
        for name in changed:
            assert name in ('word/document.xml','word/header1.xml','[Content_Types].xml')
        assert b'wordprocessingml.document.main+xml' in zo.read('[Content_Types].xml')
        print(dst,'PASS; modified parts:',', '.join(changed))
assert all(hashlib.sha256(p.read_bytes()).hexdigest()==h for p,h in before.items())
print('All input hashes unchanged. All three DOCX packages validated.')
